{
  "cases": [
    {
      "id": "C1",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Repeated testing is undocumented; silence does not establish whether it occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "The tested system scored 70% in one reported run.",
          "reason": "One reported score does not show consistency across runs."
        }
      ],
      "instrument_review": "The puzzle set and exact-grid scoring define a narrow comparison. The reported score describes one run; repeatability and score stability remain unreported."
    },
    {
      "id": "C2",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Contradicted",
          "quote": "they ran the evaluation exactly once and did not repeat it.",
          "reason": "The passage explicitly rules out repeated testing."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "they ran the evaluation exactly once and did not repeat it.",
          "reason": "A single evaluation supplies no evidence of stability or instability across runs."
        }
      ],
      "instrument_review": "Reporting clearly documents that repeatability was not tested. The 70% result describes the reported puzzle evaluation, but cannot support stable scores across runs."
    },
    {
      "id": "C3",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "Repeated evaluations under matching conditions directly test score variation."
        },
        {
          "id": "stable",
          "label": "Supported",
          "quote": "Scores ranged from 69% to 71%.",
          "reason": "The observed range meets the report's stability definition of at most two percentage points."
        }
      ],
      "instrument_review": "Repeated runs with controlled conditions support consistency under the stated definition. This evidence concerns the same system and puzzle conditions; it does not establish performance on other tasks or settings."
    },
    {
      "id": "C4",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "The developers explicitly tested variation across repeated runs under matching conditions."
        },
        {
          "id": "stable",
          "label": "Contradicted",
          "quote": "Scores ranged from 20% to 90%.",
          "reason": "This range exceeds the report's maximum of two percentage points for stability."
        }
      ],
      "instrument_review": "The repeated evaluations document substantial inconsistency under unchanged conditions. The single 70% score therefore needs the reported range alongside it for interpretation and comparison."
    },
    {
      "id": "C5",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Installation instructions do not document repeated evaluations."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "They report no additional evaluation results.",
          "reason": "The added instructions supply no evidence about score consistency."
        }
      ],
      "instrument_review": "Installation guidance explains setup, but adds no evaluation evidence. Repeatability and stability remain unknown, and the score supports only the reported grid-puzzle performance."
    },
    {
      "id": "C6",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "A solved more of the evaluated puzzles under the stated scoring and instructions."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "The evidence does not establish comparative intelligence across domains."
        }
      ],
      "instrument_review": "The results match the intended narrow comparison. Fixed instructions and exact-grid scoring provide a common basis, while other resource controls and repeated-run consistency are unspecified. Broader conclusions lack evidence."
    },
    {
      "id": "C7",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "The reported results directly favor A on the evaluated grid puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "A broader intended use does not supply evidence of intelligence across domains."
        }
      ],
      "instrument_review": "The stated use exceeds the evidence: one task domain cannot establish the supplied claim about general intelligence across domains. The narrow performance comparison is supported; repeatability and other comparison controls remain unspecified."
    },
    {
      "id": "C8",
      "probes": [
        {
          "id": "before",
          "label": "Not established",
          "quote": "Initially, only test scores were available.",
          "reason": "The initial scores alone provide no supplied evidence of improved real workshop decisions."
        },
        {
          "id": "after",
          "label": "Supported",
          "quote": "With A, 90% of decisions were correct; with B, 70%.",
          "reason": "Random allocation, blinded correctness checks, and a difference interval of 12 to 28 percentage points support better correctness with A in the studied conditions."
        },
        {
          "id": "safety",
          "label": "Not established",
          "quote": "Time and safety outcomes were not measured.",
          "reason": "Correctness findings do not establish an improvement in an unmeasured safety outcome."
        }
      ],
      "instrument_review": "The preregistered randomized trial adds direct evidence relevant to choosing assistance for correct decisions in this workshop. Blinded checks and reported uncertainty strengthen interpretation. Findings remain limited to the studied workshop and conditions; time and safety benefits are unestablished."
    }
  ],
  "closing_note": "No material instructions were unclear. Missing evidence was treated as Not established, while Contradicted was reserved for explicit conflicts."
}
